INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2300, 'educate', '/ˈedʒukeɪt/', 'verb', '{"zh-TW":["教育；培養"],"en":["to give intellectual or moral instruction"]}', NULL, 'educate the public', '[{"en":"The program aims to educate consumers about nutrition.","zh-TW":"該計畫旨在教育消費者有關營養的知識。"},{"en":"She was educated at Oxford University.","zh-TW":"她在牛津大學接受教育。"}]', '{"noun":"education/educator","verb":"educate","adjective":"educational/educated"}', NULL, 3, 2300, NULL),
(2301, 'education', 'ˌɛdʒʊˈkeɪʃən', 'noun', '{"zh-TW":["教育；學歷","培訓"],"en":["the process of learning","a person''s academic background"]}', NULL, 'higher education/continuing education', '[{"en":"Education is a key investment.","zh-TW":"教育是一項關鍵投資。"}]', '{"verb":"educate","adjective":"educational","adverb":"educationally"}', NULL, 3, 2301, NULL),
(2302, 'educational technology', '/''edʒʊˌkeɪʃənəl tekˈnɒlədʒi/', 'noun', '{"zh-TW":["教育科技；教育技術"],"en":["the use of digital tools, platforms, and resources to enhance learning and teaching"]}', NULL, 'adopt educational technology / educational technology platform / impact of educational technology', '[{"en":"Educational technology has transformed the way teachers deliver lessons.","zh-TW":"教育科技改變了教師授課的方式。"},{"en":"Many schools invest in educational technology to engage digital-native students.","zh-TW":"許多學校投資教育科技，以吸引數位原住民學生。"}]', NULL, NULL, 5, 2302, NULL),
(2303, 'effect', '/ɪˈfekt/', 'noun', '{"zh-TW":["效果；影響"],"en":["a change produced by an action or cause"]}', NULL, 'have an effect on / take effect', '[{"en":"The new law will take effect next month.","zh-TW":"新法律將於下個月生效。"},{"en":"The policy had a positive effect on sales.","zh-TW":"該政策對銷售產生了積極影響。"}]', '{"noun":"effect/effectiveness","adjective":"effective","adverb":"effectively"}', NULL, 2, 2303, NULL),
(2304, 'effective', '/ɪˈfektɪv/', 'adjective', '{"zh-TW":["有效的；效果顯著的"],"en":["producing a desired or intended result"]}', NULL, 'effective strategy / effective communication / cost-effective', '[{"en":"The training program was effective in improving sales skills.","zh-TW":"培訓計劃在提高銷售技能方面很有效果。"},{"en":"Cost-effective solutions are preferred when budgets are tight.","zh-TW":"預算緊張時，具成本效益的解決方案是首選。"}]', '{"adverb":"effectively","noun":"effectiveness","antonym":"ineffective"}', NULL, 3, 2304, 109),
(2305, 'effective date', '/ɪˈfɛktɪv deɪt/', 'noun', '{"zh-TW":["生效日期"],"en":["the date on which a contract or policy comes into force"]}', NULL, 'agreement effective date / policy effective date', '[{"en":"The contract''s effective date is the first of next month.","zh-TW":"合約的生效日期是下個月的第一天。"},{"en":"Benefits begin on the effective date of the policy.","zh-TW":"福利從保單生效日期開始生效。"}]', NULL, NULL, 5, 2305, NULL),
(2306, 'effective management', '/ɪˈfektɪv ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["有效管理"],"en":["management that achieves organizational goals through appropriate use of resources"]}', NULL, 'demonstrate effective management / principles of effective management', '[{"en":"Effective management requires clear goals, resources, and communication.","zh-TW":"有效管理需要明確的目標、資源和溝通。"},{"en":"The program taught effective management through case studies and coaching.","zh-TW":"該計劃通過案例研究和輔導教授了有效管理。"}]', NULL, NULL, 5, 2306, NULL),
(2307, 'effective tax rate', '/ɪˈfektɪv tæks reɪt/', 'noun', '{"zh-TW":["有效稅率；實際稅率"],"en":["the actual average rate at which income is taxed after deductions and credits"]}', NULL, 'calculate the effective tax rate / reduce the effective tax rate', '[{"en":"The company''s effective tax rate fell to 18% through strategic planning.","zh-TW":"通過戰略規劃，公司的有效稅率降至18%。"},{"en":"Investors compare effective tax rates across companies in different jurisdictions.","zh-TW":"投資者比較不同司法管轄區公司的有效稅率。"}]', NULL, NULL, 5, 2307, NULL),
(2308, 'effectiveness', 'ɪˈfɛktɪvnɪs', 'noun', '{"zh-TW":["有效性；效果","效力"],"en":["the quality of producing results","how well something works"]}', NULL, 'measure effectiveness/improve effectiveness', '[{"en":"We measure the effectiveness of campaigns.","zh-TW":"我們衡量活動的有效性。"}]', '{"adjective":"effective","adverb":"effectively"}', NULL, 5, 2308, NULL),
(2309, 'effectuate', '/ɪˈfektʃueɪt/', 'verb', '{"zh-TW":["實現；使生效"],"en":["to put into effect; to bring about"]}', NULL, 'effectuate a policy / effectuate change / effectuate a plan', '[{"en":"The legislation was designed to effectuate major reforms in the tax code.","zh-TW":"該立法旨在實現稅法的重大改革。"},{"en":"New management was brought in to effectuate a comprehensive restructuring.","zh-TW":"引進新管理層來實現全面的重組。"}]', '{"noun":"effectuation","adjective":"effectuated"}', NULL, 4, 2309, NULL),
(2310, 'efficacy', '/ˈefɪkəsi/', 'noun', '{"zh-TW":["效力；功效"],"en":["the ability to produce a desired result"]}', NULL, 'clinical efficacy / policy efficacy / demonstrate efficacy', '[{"en":"The clinical trial demonstrated the drug''s efficacy against the virus.","zh-TW":"臨床試驗證明了該藥物對病毒的效力。"},{"en":"Researchers measured the efficacy of the intervention across multiple outcomes.","zh-TW":"研究員在多個結果方面衡量了干預的功效。"}]', '{"adjective":"efficacious","adverb":"efficaciously"}', NULL, 3, 2310, NULL),
(2311, 'efficiency', '/ɪˈfɪʃənsi/', 'noun', '{"zh-TW":["效率；效能"],"en":["the ability to achieve a goal with minimum wasted effort"]}', NULL, 'operational efficiency / improve efficiency', '[{"en":"The new software improved workflow efficiency significantly.","zh-TW":"新軟體顯著提升了工作流程效率。"},{"en":"Efficiency is key to maintaining competitive advantage.","zh-TW":"效率是保持競爭優勢的關鍵。"}]', '{"adjective":"efficient","adverb":"efficiently"}', NULL, 4, 2311, 553),
(2312, 'efficiency ratio', '/ɪˈfɪʃənsi ˈreɪʃiəʊ/', 'noun', '{"zh-TW":["效率比率"],"en":["a measure comparing costs to revenues or outputs to inputs"]}', NULL, 'improve the efficiency ratio / calculate the efficiency ratio', '[{"en":"A lower efficiency ratio indicates better cost management.","zh-TW":"較低的效率比率表示更好的成本管理。"},{"en":"The bank''s efficiency ratio improved after restructuring.","zh-TW":"重組後銀行的效率比率有所改善。"}]', NULL, NULL, 5, 2312, NULL),
(2313, 'efficiency savings', '/ɪˈfɪʃənsi ˈseɪvɪŋz/', 'noun', '{"zh-TW":["效率節省；增效節省"],"en":["financial savings resulting from improved operational efficiency"]}', NULL, 'deliver efficiency savings / achieve efficiency savings', '[{"en":"The merger delivered 30 million in annual efficiency savings.","zh-TW":"合並帶來了每年3000萬元的效率節省。"},{"en":"Technology investment contributed significantly to efficiency savings.","zh-TW":"技術投資顯著促進了效率節省。"}]', NULL, NULL, 5, 2313, NULL),
(2314, 'efficient', '/ɪˈfɪʃənt/', 'adjective', '{"zh-TW":["高效的","有效率的"],"en":["achieving maximum output with minimum waste","achieving maximum productivity with minimum waste"]}', '{"prefix":{"text":"ef-","meaning":"out (出)"},"root":{"text":"fic","meaning":"make/do (做)"},"suffix":{"text":"-ient","meaning":"being (…的)"},"logic":"做出成果的，即「有效率的」。"}', 'cost-efficient / energy-efficient; energy-efficient / cost-efficient / highly efficient', '[{"en":"The new system is more efficient.","zh-TW":"新系統更加高效。"},{"en":"We need to find a more efficient solution.","zh-TW":"我們需要找到更高效的解決方案。"},{"en":"This engine is more fuel-efficient.","zh-TW":"這個引擎更省油。"},{"en":"We need a more efficient way to process orders.","zh-TW":"我們需要更有效率的方式處理訂單。"}]', '{"noun":"efficiency","adjective":"efficient","adverb":"efficiently"}', NULL, 3, 2314, 110),
(2315, 'effort', '/ˈefərt/', 'noun', '{"zh-TW":["努力；成果"],"en":["a determined attempt; physical or mental energy used"]}', NULL, 'make an effort / considerable effort', '[{"en":"It took a lot of effort to complete the project.","zh-TW":"完成這個項目花了很多努力。"},{"en":"Please make an effort to arrive on time.","zh-TW":"請努力準時到達。"}]', '{"noun":"effort","adjective":"effortless"}', NULL, 2, 2315, NULL),
(2316, 'egalitarianism', '/ɪˌɡælɪˈteəriənɪzəm/', 'noun', '{"zh-TW":["平等主義"],"en":["the belief in and pursuit of equal rights and opportunities for all people"]}', NULL, 'promote egalitarianism / social egalitarianism / egalitarianism in education', '[{"en":"Egalitarianism in education requires removing barriers that limit disadvantaged students.","zh-TW":"教育上的平等主義需要消除限制弱勢學生的障礙。"},{"en":"Critics argue that strict egalitarianism ignores differences in individual merit.","zh-TW":"批評者認為，嚴格的平等主義忽視了個人才能的差異。"}]', '{"adjective":"egalitarian","noun2":"egalitarian"}', NULL, 5, 2316, NULL),
(2317, 'ekphrasis', '/ˈekfrəsɪs/', 'noun', '{"zh-TW":["對視覺藝術的文字描述"],"en":["a literary description or commentary on a visual work of art"]}', NULL, 'ekphrasis poem / practice ekphrasis / ekphrasis in literature', '[{"en":"Keats''s Ode on a Grecian Urn is a celebrated example of ekphrasis.","zh-TW":"濟慈的《希臘古甕頌》是一個著名的對視覺藝術的文字描述例子。"},{"en":"Ekphrasis transforms the experience of visual art into language.","zh-TW":"對視覺藝術的文字描述將視覺藝術體驗轉化為語言。"}]', '{"adjective":"ekphrastic"}', NULL, 3, 2317, NULL),
(2318, 'elaborate', '/ɪˈlæbərət/', 'adjective / verb', '{"zh-TW":["精心的；詳述"],"en":["detailed and complicated; to explain in more detail"]}', NULL, 'elaborate on/plan', '[{"en":"Could you elaborate on your proposal?","zh-TW":"你能詳細說明你的提案嗎？"},{"en":"They developed an elaborate marketing strategy.","zh-TW":"他們制定了精心的行銷策略。"}]', '{"noun":"elaboration","verb":"elaborate","adjective":"elaborate"}', NULL, 3, 2318, 676),
(2319, 'elaborate on', '/''ɪˌlæbəreɪt ɒn/', 'phrase', '{"zh-TW":["詳細說明；進一步闡述"],"en":["to add more detail or information about a topic"]}', NULL, 'elaborate on a point / elaborate on an idea / elaborate on findings', '[{"en":"Could you elaborate on the reasons behind your decision?","zh-TW":"你能詳細說明你做出這個決定的原因嗎？"},{"en":"The speaker elaborated on the key challenges facing the industry today.","zh-TW":"演講者詳細闡述了當今行業面臨的關鍵挑戰。"}]', NULL, NULL, 4, 2319, NULL),
(2320, 'elasticity', '/ˌɪlæˈstɪsɪti/', 'noun', '{"zh-TW":["彈性"],"en":["the degree to which demand responds to a change in price"]}', NULL, 'price elasticity / demand elasticity / income elasticity', '[{"en":"The price elasticity of cigarettes is low because they are addictive.","zh-TW":"香菸的價格彈性低，因為它們具有成癮性。"},{"en":"Understanding elasticity helps firms set optimal pricing strategies.","zh-TW":"了解彈性幫助企業制定最佳定價策略。"}]', '{"adjective":"elastic","adverb":"elastically"}', NULL, 4, 2320, NULL),
(2321, 'elasticity of demand', '/ˌɪlæˈstɪsɪti əv dɪˈmɑːnd/', 'noun', '{"zh-TW":["需求彈性"],"en":["the degree to which consumer demand changes in response to a price change"]}', NULL, 'measure elasticity of demand / inelastic demand', '[{"en":"Luxury goods have high elasticity of demand and sales drop with price rises.","zh-TW":"奢侈品的需求彈性高，價格上漲時銷售量下降。"},{"en":"Essential services have low elasticity of demand regardless of price.","zh-TW":"基本服務無論價格如何都具有低需求彈性。"}]', NULL, NULL, 5, 2321, NULL),
(2322, 'elect', '/ɪˈlekt/', 'verb', '{"zh-TW":["選舉；選擇"],"en":["to choose by voting"]}', NULL, 'elect a president/chairperson', '[{"en":"She was elected as the new chairperson.","zh-TW":"她被選為新主席。"},{"en":"Members elect the board annually.","zh-TW":"成員每年選舉董事會。"}]', '{"noun":"election","verb":"elect","adjective":"elected/electoral"}', NULL, 2, 2322, NULL),
(2323, 'elective', '/ɪˈlɛktɪv/', 'noun', '{"zh-TW":["選修課"],"en":["a course that students can choose to take"]}', NULL, 'elective course / take an elective', '[{"en":"Art is an elective at our school.","zh-TW":"藝術在我們學校是選修課。"},{"en":"Students must take two electives.","zh-TW":"學生必須選修兩門選修課。"}]', NULL, NULL, 3, 2323, NULL),
(2324, 'elective course', '/''ɪˈlektɪv kɔːrs/', 'noun', '{"zh-TW":["選修課程"],"en":["an optional course chosen by a student from a range of options to complement their main studies"]}', NULL, 'take an elective course / choose an elective course / elective course options', '[{"en":"She chose creative writing as an elective course to complement her journalism degree.","zh-TW":"她選擇創意寫作作為選修課程，以補充她的新聞學學位。"},{"en":"Students must complete two elective courses outside their major field.","zh-TW":"學生必須在主修領域之外完成兩門選修課程。"}]', NULL, NULL, 5, 2324, NULL),
(2325, 'elective deferral', '/ɪˈlektɪv dɪˈfɜːrəl/', 'noun', '{"zh-TW":["自願遞延；自選遞延"],"en":["a voluntary contribution to a retirement plan made by an employee from pre-tax income"]}', NULL, 'make an elective deferral / elective deferral limit', '[{"en":"Employees can increase their elective deferral up to the annual contribution limit.","zh-TW":"員工可以將其自願遞延增加到年度供款上限。"},{"en":"Elective deferrals reduce current taxable income and grow tax-deferred.","zh-TW":"自願遞延降低了當前應稅收入並延稅增長。"}]', NULL, NULL, 5, 2325, NULL),
(2326, 'electric vehicle', '/ɪˈlɛktrɪk ˈviːɪkəl/', 'noun', '{"zh-TW":["電動車"],"en":["a vehicle powered by electricity rather than fossil fuels"]}', NULL, 'drive an electric vehicle / electric vehicle charging', '[{"en":"Electric vehicles produce no direct carbon emissions.","zh-TW":"電動車不直接產生碳排放。"},{"en":"The government offers subsidies for purchasing electric vehicles.","zh-TW":"政府為購買電動車提供補貼。"}]', '{"abbreviation":"EV"}', NULL, 5, 2326, NULL),
(2327, 'electrocardiogram', '/ɪˌlɛktrəʊˈkɑːrdiəˌɡræm/', 'noun', '{"zh-TW":["心電圖"],"en":["a recording of the electrical activity of the heart"]}', NULL, 'perform an electrocardiogram / electrocardiogram results', '[{"en":"The doctor ordered an electrocardiogram to check heart rhythm.","zh-TW":"醫生要求進行心電圖以檢查心律。"},{"en":"An electrocardiogram is a painless and non-invasive test.","zh-TW":"心電圖是無痛且非侵入性的測試。"}]', '{"abbreviation":"ECG","abbreviation2":"EKG"}', NULL, 5, 2327, NULL),
(2328, 'electrolyte', '/''ɪˌlektrəˌlaɪt/', 'noun', '{"zh-TW":["電解質"],"en":["a mineral in the body, such as sodium or potassium, that carries an electric charge and is essential for various body functions"]}', NULL, 'replenish electrolytes / electrolyte balance / electrolyte drink', '[{"en":"Athletes drink sports beverages to replenish electrolytes lost through sweat.","zh-TW":"運動員飲用運動飲料以補充汗液流失的電解質。"},{"en":"An electrolyte imbalance can cause fatigue, cramping, and dizziness.","zh-TW":"電解質失衡可能導致疲勞、痙攣和頭暈。"}]', '{"adjective":"electrolytic"}', NULL, 4, 2328, NULL),
(2329, 'electronic data interchange', '/ɪˌlektrɒnɪk ˈdeɪtə ˈɪntətʃeɪndʒ/', 'noun', '{"zh-TW":["電子數據交換"],"en":["the computer-to-computer exchange of business documents in a standard format"]}', NULL, 'implement electronic data interchange / electronic data interchange standards', '[{"en":"Electronic data interchange speeds up order processing between trading partners.","zh-TW":"電子數據交換加快了貿易夥伴之間的訂單處理。"},{"en":"Many large retailers require suppliers to use electronic data interchange.","zh-TW":"許多大型零售商要求供應商使用電子數據交換。"}]', '{"abbreviation":"EDI"}', NULL, 5, 2329, NULL),
(2330, 'electronic health record', '/ɪˌlektrɒnɪk helθ ˈrekɔːrd/', 'noun', '{"zh-TW":["電子健康記錄"],"en":["a digital version of a patient''s medical history and health information"]}', NULL, 'access electronic health records / electronic health record system / share electronic health records', '[{"en":"Electronic health records improve care coordination between providers.","zh-TW":"電子健康記錄改善了醫療提供者之間的護理協調。"},{"en":"Patients can view their electronic health records through a secure portal.","zh-TW":"患者可以通過安全門戶查看他們的電子健康記錄。"}]', NULL, NULL, 5, 2330, NULL),
(2331, 'element', '/ˈelɪmənt/', 'noun', '{"zh-TW":["要素；元素"],"en":["a component or part of something"]}', NULL, 'key/essential element', '[{"en":"Trust is a key element of teamwork.","zh-TW":"信任是團隊合作的關鍵要素。"},{"en":"The plan has several important elements.","zh-TW":"該計畫有幾個重要的要素。"}]', '{"noun":"element","adjective":"elementary"}', NULL, 3, 2331, NULL),
(2332, 'elevate', '/ˈelɪveɪt/', 'verb', '{"zh-TW":["提升；提高"],"en":["to raise to a higher position or level"]}', NULL, 'elevate standards/status', '[{"en":"The promotion elevated her to senior manager.","zh-TW":"升遷使她晉升為高級經理。"},{"en":"We aim to elevate customer experience.","zh-TW":"我們的目標是提升客戶體驗。"}]', '{"noun":"elevation/elevator","verb":"elevate","adjective":"elevated"}', NULL, 3, 2332, NULL),
(2333, 'elevator', '/''elɪveɪtər/', 'noun', '{"zh-TW":["電梯；升降機"],"en":["a platform or compartment housed in a shaft for raising and lowering people or things"]}', NULL, 'take the elevator / elevator button / elevator lobby', '[{"en":"Please take the elevator to the fifth floor to reach the conference room.","zh-TW":"請乘電梯到五樓到達會議室。"},{"en":"The hotel''s glass elevator offered a spectacular view of the atrium.","zh-TW":"飯店的玻璃電梯可以看到中庭的壯觀景色。"}]', NULL, NULL, 3, 2333, NULL),
(2334, 'elevator pitch', '/ˈelɪveɪtər pɪtʃ/', 'noun', '{"zh-TW":["電梯簡報；簡短推銷"],"en":["a brief persuasive speech used to spark interest in what you do"]}', NULL, 'prepare an elevator pitch / deliver an elevator pitch / perfect your elevator pitch', '[{"en":"His elevator pitch convinced the investor to request a full meeting.","zh-TW":"他的電梯簡報說服了投資者要求進行完整的會面。"},{"en":"Every entrepreneur should have a polished elevator pitch ready.","zh-TW":"每位創業家都應該準備好一個精心打磨的電梯簡報。"}]', NULL, NULL, 5, 2334, NULL),
(2335, 'elicit', '/ɪˈlɪsɪt/', 'verb', '{"zh-TW":["引出；誘導"],"en":["to draw out a response, answer, or fact from someone"]}', NULL, 'elicit a response / elicit information / elicit feedback', '[{"en":"Open-ended questions elicit more detailed answers.","zh-TW":"開放式問題能引出更詳細的回答。"},{"en":"The researcher elicited candid opinions through interviews.","zh-TW":"研究員通過訪談引出了坦率的意見。"}]', NULL, NULL, 2, 2335, NULL),
(2336, 'eligible', '/ˈelɪdʒəbəl/', 'adjective', '{"zh-TW":["合格的；有資格的"],"en":["meeting the conditions to do or receive something"]}', NULL, 'eligible for/to', '[{"en":"All full-time employees are eligible for benefits.","zh-TW":"所有全職員工都有資格享受福利。"},{"en":"You must be 18 to be eligible to vote.","zh-TW":"你必須年滿18歲才有投票資格。"}]', '{"noun":"eligibility","adjective":"eligible"}', NULL, 3, 2336, 866),
(2337, 'eligible expense', '/ˈelɪdʒɪbəl ɪkˈspens/', 'noun', '{"zh-TW":["合資格費用；可報銷費用"],"en":["an expense that qualifies for reimbursement or tax deduction under specific rules"]}', NULL, 'claim eligible expenses / eligible expense policy', '[{"en":"Only eligible expenses as per the policy are reimbursed.","zh-TW":"只有符合政策的合資格費用才能報銷。"},{"en":"The accountant reviewed all receipts to identify eligible expenses.","zh-TW":"會計師審查了所有收據以識別合資格費用。"}]', NULL, NULL, 5, 2337, NULL),
(2338, 'eliminate', '/ɪˈlɪmɪneɪt/', 'verb', '{"zh-TW":["消除；淘汰"],"en":["to completely remove or get rid of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"limin","meaning":"threshold (門檻)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使超出門檻之外，即「淘汰」。"}', 'eliminate waste/errors; eliminate waste / eliminate the possibility', '[{"en":"We need to eliminate unnecessary costs.","zh-TW":"我們需要消除不必要的成本。"},{"en":"The company eliminated 200 positions.","zh-TW":"公司裁撤了200個職位。"},{"en":"The team was eliminated in the first round.","zh-TW":"該隊在第一輪就被淘汰了。"}]', '{"noun":"elimination","verb":"eliminate"}', NULL, 3, 2338, 342),
(2339, 'elite theory', '/ɪˈliːt ˈθɪəri/', 'noun', '{"zh-TW":["精英理論"],"en":["the political theory that a small elite group holds power in society"]}', NULL, 'apply elite theory / elite theory of democracy / challenge elite theory', '[{"en":"Elite theory argues that democracy is in practice controlled by a small group.","zh-TW":"精英理論認為民主在實踐中由一小群人控制。"},{"en":"Elite theory challenges pluralist views of power distribution.","zh-TW":"精英理論挑戰了關於權力分配的多元主義觀點。"}]', NULL, NULL, 4, 2339, NULL),
(2340, 'eloquence', '/''eləkwəns/', 'noun', '{"zh-TW":["口才；雄辯"],"en":["the ability to speak or write effectively and persuasively"]}', NULL, 'demonstrate eloquence / eloquence in speech / renowned for eloquence', '[{"en":"Her eloquence in the debate persuaded many undecided voters.","zh-TW":"她在辯論中的口才說服了許多未決定的選民。"},{"en":"The politician was celebrated for his eloquence and ability to inspire crowds.","zh-TW":"這位政治家因其口才和鼓舞人心的能力而備受讚揚。"}]', '{"adjective":"eloquent","adverb":"eloquently"}', NULL, 3, 2340, NULL),
(2341, 'eloquent', '/''eləkwənt/', 'adjective', '{"zh-TW":["雄辯的；有說服力的"],"en":["fluent or persuasive in speaking or writing"]}', NULL, 'eloquent speaker / eloquent speech / eloquent argument', '[{"en":"The CEO delivered an eloquent speech that inspired employees at all levels.","zh-TW":"首席執行官發表了一篇雄辯的演講，激勵了各個層次的員工。"},{"en":"An eloquent letter of complaint is more likely to receive a positive response.","zh-TW":"一封雄辯的投訴信更有可能獲得積極的回應。"}]', '{"adverb":"eloquently","noun":"eloquence"}', NULL, 3, 2341, NULL),
(2342, 'eloquently', '/''eləkwəntli/', 'adverb', '{"zh-TW":["雄辯地；有說服力地"],"en":["in a fluent, persuasive, and clearly expressed manner"]}', NULL, 'argue eloquently / express eloquently / speak eloquently', '[{"en":"She argued eloquently for the importance of investing in employee training.","zh-TW":"她雄辯地論證了投資員工培訓的重要性。"},{"en":"The director expressed eloquently how innovation drives the company''s vision.","zh-TW":"總監雄辯地表達了創新如何驅動公司願景。"}]', NULL, NULL, 4, 2342, NULL),
(2343, 'elucidate', '/ɪˈluːsɪdeɪt/', 'verb', '{"zh-TW":["闡明；解釋清楚"],"en":["to make something clear; to explain in detail"]}', NULL, 'elucidate a point / elucidate findings / elucidate a concept', '[{"en":"The professor elucidated the complex theorem with examples.","zh-TW":"教授用例子闡明了這個複雜的定理。"},{"en":"Could you elucidate what you mean by that statement?","zh-TW":"你能闡明你那句話的意思嗎？"}]', '{"noun":"elucidation","adjective":"elucidatory"}', NULL, 3, 2343, NULL),
(2344, 'elusive', '/''ɪˌluːsɪv/', 'adjective', '{"zh-TW":["難以捉摸的；難以達到的"],"en":["difficult to find, catch, or achieve; avoiding capture"]}', NULL, 'elusive goal / elusive answer / elusive solution', '[{"en":"The solution to the problem remained elusive despite months of research.","zh-TW":"儘管研究了數月，這個問題的解決方案仍然難以捉摸。"},{"en":"The elusive figure disappeared before the investigators could gather any evidence.","zh-TW":"這個難以捉摸的人物在調查人員收集任何證據之前就消失了。"}]', '{"adverb":"elusively","noun":"elusiveness","verb":"elude"}', NULL, 3, 2344, NULL),
(2345, 'email', 'ˈiːmeɪl', 'noun', '{"zh-TW":["電子郵件；電子信件","郵件"],"en":["a message sent electronically","an electronic message system"]}', NULL, 'send an email/check email', '[{"en":"Please check your email for the attachment.","zh-TW":"請查看您的電子郵件以獲取附件。"}]', '{"verb":"email","adjective":"email-based"}', NULL, 2, 2345, NULL),
(2346, 'email marketing', '/ˈiːmeɪl ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["電子郵件行銷"],"en":["using email to promote products and build customer relationships"]}', NULL, 'email marketing campaign / email marketing platform / email marketing automation', '[{"en":"Their email marketing campaign achieved a 25% open rate.","zh-TW":"他們的電子郵件行銷活動達到了25%的開信率。"},{"en":"Personalized email marketing improves click-through rates.","zh-TW":"個人化電子郵件行銷提高了點擊率。"}]', '{"noun":"email marketer"}', NULL, 5, 2346, NULL),
(2347, 'embargo', '/ɪmˈbɑːrɡəʊ/', 'noun', '{"zh-TW":["禁運令；貿易禁令"],"en":["an official ban on trade with a particular country"]}', NULL, 'impose an embargo / lift an embargo', '[{"en":"The government imposed an embargo on the export of technology.","zh-TW":"政府對技術出口實施了禁運令。"},{"en":"Lifting the trade embargo opened new market opportunities.","zh-TW":"解除貿易禁令開闢了新的市場機會。"}]', '{"verb":"embargo"}', NULL, 3, 2347, NULL),
(2348, 'embargo on imports', '/ɪmˈbɑːrɡoʊ ɒn ˈɪmpɔːrts/', 'noun', '{"zh-TW":["進口禁令"],"en":["a government ban on importing specific goods"]}', NULL, 'impose an embargo on imports / lift the embargo on imports', '[{"en":"The embargo on imports was lifted after diplomatic relations improved.","zh-TW":"隨著外交關係改善，進口禁令被解除了。"},{"en":"An embargo on imports was imposed to protect domestic producers.","zh-TW":"為保護國內生產商，進口禁令被實施了。"}]', NULL, NULL, 5, 2348, NULL),
(2349, 'embargo period', '/ɪmˈbɑːrɡoʊ ˌpɪəriəd/', 'noun', '{"zh-TW":["禁止期；封鎖期"],"en":["a period during which specific information or goods cannot be released"]}', NULL, 'observe the embargo period / during the embargo period', '[{"en":"Financial results are under an embargo period before the announcement.","zh-TW":"財務業績在公告前處於禁止期。"},{"en":"Press releases are shared in advance with an embargo period attached.","zh-TW":"新聞稿提前共享，並附有禁止期。"}]', NULL, NULL, 5, 2349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2350, 'embark', '/ɪmˈbɑːrk/', 'verb', '{"zh-TW":["登船；開始"],"en":["to get on a ship or aircraft"]}', NULL, 'embark on a journey / embark passengers', '[{"en":"Passengers began to embark at noon.","zh-TW":"乘客在中午開始登船。"},{"en":"They embarked on an exciting new adventure.","zh-TW":"他們踏上了令人興奮的新冒險。"}]', '{"noun":"embarkation"}', NULL, 2, 2350, NULL),
(2351, 'embark on', '/''ɪmˌbɑːrk ɒn/', 'phrase', '{"zh-TW":["著手；開始"],"en":["to begin a new journey, project, or endeavor"]}', NULL, 'embark on a journey / embark on a new project / embark on a career', '[{"en":"She decided to embark on a new career in environmental consulting.","zh-TW":"她決定踏上環境諮詢的新職業道路。"},{"en":"The company is embarking on its biggest expansion in a decade.","zh-TW":"公司正在著手進行十年來最大的擴張。"}]', '{"verb":"embark","noun":"embarkation"}', NULL, 3, 2351, NULL),
(2352, 'embarkation', '/ˌɛmbɑːrˈkeɪʃən/', 'noun', '{"zh-TW":["登船；登機"],"en":["the action of getting on a ship or aircraft"]}', NULL, 'embarkation point / embarkation card', '[{"en":"Embarkation will begin at the main gate.","zh-TW":"登船將在主閘口開始。"},{"en":"Please complete the embarkation card before arrival.","zh-TW":"請在抵達前填妥入境卡。"}]', '{"verb":"embark"}', NULL, 4, 2352, NULL),
(2353, 'embarrassed', '/ɪmˈbærəst/', 'adjective', '{"zh-TW":["尷尬的；難為情的"],"en":["feeling ashamed or shy"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"barrass","meaning":"bar/obstruct (阻礙)"},"suffix":{"text":"-ed","meaning":"feeling (感受)"},"logic":"感覺被阻礙住的，即「尷尬的」。"}', 'feel embarrassed / embarrassed about', '[{"en":"He was embarrassed by his mistake.","zh-TW":"他因犯錯而感到尷尬。"},{"en":"She felt embarrassed in front of everyone.","zh-TW":"她在眾人面前感到難為情。"}]', '{"noun":"embarrassment","adjective":"embarrassing","verb":"embarrass"}', NULL, 4, 2353, NULL),
(2354, 'embassy', '/''embəsi/', 'noun', '{"zh-TW":["大使館"],"en":["the official residence or offices of an ambassador"]}', NULL, 'visit an embassy / report to an embassy / embassy staff', '[{"en":"Travelers in trouble abroad should contact their country''s embassy.","zh-TW":"在海外遇到麻煩的旅客應聯繫本國大使館。"},{"en":"She applied for her travel visa at the foreign embassy.","zh-TW":"她在外國大使館申請了旅遊簽證。"}]', '{"adjective":"ambassadorial"}', NULL, 3, 2354, NULL),
(2355, 'embedded system', '/ɪmˈbedɪd ˈsɪstəm/', 'noun', '{"zh-TW":["嵌入式系統"],"en":["a computer system built into a device to perform specific functions"]}', NULL, 'design an embedded system / embedded system firmware / real-time embedded system', '[{"en":"Modern cars contain dozens of embedded systems for various functions.","zh-TW":"現代汽車包含數十個嵌入式系統用於各種功能。"},{"en":"Medical devices rely on reliable embedded systems for patient safety.","zh-TW":"醫療設備依賴可靠的嵌入式系統來確保患者安全。"}]', NULL, NULL, 5, 2355, NULL),
(2356, 'embezzlement', '/ɪmˈbezəlmənt/', 'noun', '{"zh-TW":["侵吞；挪用公款"],"en":["the theft or misappropriation of funds placed in one''s trust"]}', NULL, 'charged with embezzlement / embezzlement of public funds / corporate embezzlement', '[{"en":"The treasurer was convicted of embezzlement after diverting client funds to personal accounts.","zh-TW":"財務主管在將客戶資金轉移到個人帳戶後被判定犯有挪用公款罪。"},{"en":"Embezzlement in the nonprofit sector often goes undetected due to weak internal controls.","zh-TW":"由於內部控制薄弱，非盈利部門的挪用公款行為往往未被發現。"}]', '{"verb":"embezzle","noun2":"embezzler"}', NULL, 4, 2356, NULL),
(2357, 'embrace', '/ɪmˈbreɪs/', 'verb', '{"zh-TW":["擁抱；接受"],"en":["to accept willingly; to hold closely"]}', NULL, 'embrace change/technology', '[{"en":"Companies must embrace new technology.","zh-TW":"企業必須擁抱新技術。"},{"en":"She embraced the opportunity eagerly.","zh-TW":"她熱切地接受了這個機會。"}]', '{"noun":"embrace","verb":"embrace"}', NULL, 3, 2357, NULL),
(2358, 'emerge', '/ɪˈmɜːrdʒ/', 'verb', '{"zh-TW":["出現；浮現"],"en":["to come into view; to become known","to come into view or existence"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"merge","meaning":"dip/plunge (浸入)"},"logic":"從水中浮出，即「出現」。"}', 'emerge as/from; emerge from / emerging market / emerge as', '[{"en":"New competitors are emerging in the market.","zh-TW":"市場上出現了新的競爭者。"},{"en":"The company emerged as a market leader.","zh-TW":"該公司成為市場領導者。"},{"en":"New evidence emerged during the investigation.","zh-TW":"調查期間浮現了新證據。"},{"en":"She emerged as the leading candidate.","zh-TW":"她脫穎而出成為領先的候選人。"}]', '{"noun":"emergence","verb":"emerge","adjective":"emerging/emergent"}', NULL, 2, 2358, NULL),
(2359, 'emergency', '/ɪˈmɜːrdʒənsi/', 'noun', '{"zh-TW":["緊急情況"],"en":["a serious unexpected situation requiring immediate action"]}', NULL, 'in case of emergency', '[{"en":"Call 911 in case of an emergency.","zh-TW":"緊急情況下請撥打911。"},{"en":"An emergency meeting was called.","zh-TW":"召開了緊急會議。"}]', '{"noun":"emergency","adjective":"emergency"}', NULL, 3, 2359, 343),
(2360, 'emergency contact', '/ɪˈmɜːrdʒənsi ˈkɒntækt/', 'noun', '{"zh-TW":["緊急聯絡人"],"en":["a person to be notified in case of an emergency"]}', NULL, 'list an emergency contact / emergency contact form', '[{"en":"Please provide an emergency contact on the registration form.","zh-TW":"請在登記表上提供緊急聯絡人。"},{"en":"The hospital called the patient''s emergency contact.","zh-TW":"醫院聯絡了患者的緊急聯絡人。"}]', NULL, NULL, 5, 2360, NULL),
(2361, 'emergency exit', '/ɪˈmɜːrdʒənsi ˈɛɡzɪt/', 'noun', '{"zh-TW":["緊急出口；安全出口"],"en":["a door used to escape a building in an emergency"]}', NULL, 'locate the emergency exit / emergency exit sign', '[{"en":"Familiarize yourself with the emergency exits upon arrival.","zh-TW":"抵達時請熟悉緊急出口的位置。"},{"en":"Emergency exit signs must be illuminated at all times.","zh-TW":"緊急出口標誌必須始終保持照明。"}]', NULL, NULL, 5, 2361, NULL),
(2362, 'emergency surgery', '/ɪˈmɜːrdʒənsi ˈsɜːrdʒəri/', 'noun', '{"zh-TW":["緊急手術"],"en":["an operation performed urgently to save a life"]}', NULL, 'undergo emergency surgery / perform emergency surgery', '[{"en":"He underwent emergency surgery after the accident.","zh-TW":"他在事故後接受了緊急手術。"},{"en":"The hospital''s surgical team is available for emergency surgery 24 hours.","zh-TW":"醫院的外科團隊全天24小時提供緊急手術服務。"}]', NULL, NULL, 5, 2362, NULL),
(2363, 'emerging market', '/ɪˈmɜːrdʒɪŋ ˈmɑːrkɪt/', 'noun', '{"zh-TW":["新興市場"],"en":["a developing economy with growing investment potential"]}', NULL, 'invest in emerging markets / expanding into emerging markets', '[{"en":"The fund allocates 30% of assets to emerging markets.","zh-TW":"基金將30%的資產配置到新興市場。"},{"en":"Emerging markets offer high growth but also higher risk.","zh-TW":"新興市場提供高增長但也有更高的風險。"}]', NULL, NULL, 5, 2363, NULL),
(2364, 'emerging markets', '/ɪˈmɜːrdʒɪŋ ˈmɑːrkɪts/', 'noun', '{"zh-TW":["新興市場"],"en":["developing countries whose economies are growing rapidly and becoming more integrated globally"]}', NULL, 'invest in emerging markets / emerging markets growth / emerging markets risk', '[{"en":"Emerging markets offer higher growth potential but also greater volatility for investors.","zh-TW":"新興市場為投資者提供了更高的增長潛力，但也帶來了更大的波動性。"},{"en":"Capital flows to emerging markets accelerated as interest rates fell in developed economies.","zh-TW":"隨著發達經濟體利率下降，資本流向新興市場加速。"}]', NULL, NULL, 5, 2364, NULL),
(2365, 'eminent domain', '/ˈemɪnənt dəˈmeɪn/', 'noun', '{"zh-TW":["徵用權；土地徵收權"],"en":["the government''s power to take private property for public use with compensation"]}', NULL, 'exercise eminent domain / eminent domain proceedings / just compensation for eminent domain', '[{"en":"The government used eminent domain to acquire land for the new highway.","zh-TW":"政府行使徵用權徵收土地用於新高速公路。"},{"en":"Property owners must receive fair compensation when eminent domain is exercised.","zh-TW":"行使徵用權時，財產所有人必須獲得公平補償。"}]', NULL, NULL, 5, 2365, NULL),
(2366, 'emission', '/ɪˈmɪʃən/', 'noun', '{"zh-TW":["排放；排放物"],"en":["the production and discharge of something, especially gas"]}', NULL, 'carbon/greenhouse emissions', '[{"en":"The factory must reduce its carbon emissions.","zh-TW":"工廠必須減少碳排放。"},{"en":"Emission standards are becoming stricter.","zh-TW":"排放標準越來越嚴格。"}]', '{"noun":"emission","verb":"emit"}', NULL, 3, 2366, NULL),
(2367, 'emission reduction', '/ɪˈmɪʃən rɪˈdʌkʃən/', 'noun', '{"zh-TW":["減排；降低排放量"],"en":["the decrease of pollutants released into the atmosphere"]}', NULL, 'achieve emission reductions / emission reduction target', '[{"en":"The government set ambitious emission reduction targets.","zh-TW":"政府設定了雄心勃勃的減排目標。"},{"en":"Emission reduction requires changes in energy use and transport.","zh-TW":"減排需要改變能源使用和交通方式。"}]', NULL, NULL, 5, 2367, NULL),
(2368, 'emissions trading', '/ɪˈmɪʃənz ˈtreɪdɪŋ/', 'noun', '{"zh-TW":["排放交易；碳排放交易"],"en":["a market-based system where companies buy and sell emission permits"]}', NULL, 'emissions trading scheme / international emissions trading / cap-and-trade emissions trading', '[{"en":"Emissions trading creates economic incentives to reduce pollution.","zh-TW":"排放交易為減少污染創造了經濟激勵。"},{"en":"The EU emissions trading system covers aviation and heavy industry.","zh-TW":"歐盟排放交易體系涵蓋航空業和重工業。"}]', NULL, NULL, 5, 2368, NULL),
(2369, 'emotion', '/ɪˈmoʊʃn/', 'noun', '{"zh-TW":["情緒；情感"],"en":["a strong feeling such as joy, anger, or sadness"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"mot","meaning":"move (移動)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"從內心移動出來的感覺，即「情緒」。"}', 'strong emotion / show emotion / mixed emotions', '[{"en":"She couldn''t hide her emotions.","zh-TW":"她無法隱藏自己的情緒。"},{"en":"The movie evoked strong emotions.","zh-TW":"這部電影激發了強烈的情感。"}]', '{"adjective":"emotional","adverb":"emotionally"}', NULL, 3, 2369, NULL),
(2370, 'emotional intelligence', '/''ɪˌməʊʃənəl ɪnˌtelɪdʒəns/', 'noun', '{"zh-TW":["情緒智力；EQ"],"en":["the capacity to be aware of, control, and express one''s emotions and to handle interpersonal relationships empathetically"]}', NULL, 'develop emotional intelligence / high emotional intelligence / benefit of emotional intelligence', '[{"en":"Leaders with high emotional intelligence are better at managing teams and resolving conflicts.","zh-TW":"具有高情緒智力的領導者在管理團隊和解決衝突方面更有能力。"},{"en":"Emotional intelligence is increasingly valued alongside technical skills in the workplace.","zh-TW":"在職場中，情緒智力與技術技能一同越來越受到重視。"}]', '{"adjective":"emotional","noun2":"EQ"}', NULL, 5, 2370, NULL),
(2371, 'empathy', '/ˈempəθi/', 'noun', '{"zh-TW":["同理心"],"en":["the ability to understand and share another''s feelings"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"path","meaning":"feeling (感受)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"進入他人感受中，即「同理心」。"}', 'show empathy / lack of empathy', '[{"en":"A good therapist shows empathy toward patients.","zh-TW":"好的治療師對病人展現同理心。"},{"en":"Empathy is important in building relationships.","zh-TW":"同理心在建立關係中很重要。"}]', '{"adjective":"empathetic","verb":"empathize"}', NULL, 3, 2371, NULL),
(2372, 'emphasis', '/ˈemfəsɪs/', 'noun', '{"zh-TW":["強調；重點"],"en":["special importance given to something"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"phas","meaning":"show (展現)"},"suffix":{"text":"-is","meaning":"state (狀態)"},"logic":"在其中展現出重要性，即「強調」。"}', 'place/put emphasis on; place emphasis on / with emphasis / special emphasis', '[{"en":"The company places great emphasis on quality.","zh-TW":"公司非常重視品質。"},{"en":"There is growing emphasis on sustainability.","zh-TW":"對永續發展的重視日益增長。"},{"en":"The school places emphasis on creative thinking.","zh-TW":"學校強調創意思考。"},{"en":"She spoke with great emphasis.","zh-TW":"她說話時特別加重語氣。"}]', '{"noun":"emphasis","verb":"emphasize","adjective":"emphatic"}', NULL, 3, 2372, NULL),
(2373, 'emphasize', '/ˈɛmfəsaɪz/', 'verb', '{"zh-TW":["強調；重視"],"en":["to give special attention to something"]}', NULL, 'emphasize the importance / emphasize key points', '[{"en":"The manager emphasized the importance of meeting deadlines.","zh-TW":"經理強調了按時完成工作的重要性。"},{"en":"Please emphasize the key benefits in your presentation.","zh-TW":"請在您的簡報中強調主要優勢。"}]', '{"noun":"emphasis","adjective":"emphatic"}', NULL, 3, 2373, NULL),
(2374, 'empirical', '/ɪmˈpɪrɪkəl/', 'adjective', '{"zh-TW":["實證的；以觀察為基礎的"],"en":["based on or verifiable by observation or experience"]}', NULL, 'empirical evidence / empirical study / empirical findings', '[{"en":"The empirical evidence supports the proposed theory.","zh-TW":"實證數據支持所提出的理論。"},{"en":"An empirical approach requires collecting measurable data.","zh-TW":"實證方法需要收集可測量的數據。"}]', '{"adverb":"empirically","noun":"empiricism"}', NULL, 3, 2374, NULL),
(2375, 'empirically', '/ɪmˈpɪrɪkli/', 'adverb', '{"zh-TW":["實證地；憑經驗地"],"en":["in a way based on observation or experience"]}', NULL, 'empirically tested / empirically supported / empirically validated', '[{"en":"The hypothesis was empirically tested across three different populations.","zh-TW":"假設在三個不同的人群中進行了實證測試。"},{"en":"Empirically grounded recommendations carry greater scientific authority.","zh-TW":"實證支持的建議具有更大的科學權威性。"}]', '{"adjective":"empirical","noun":"empiricism"}', NULL, 4, 2375, NULL),
(2376, 'empiricism', '/ɪmˈpɪrɪsɪzəm/', 'noun', '{"zh-TW":["經驗主義；實證論"],"en":["the theory that all knowledge is based on experience and observation"]}', NULL, 'scientific empiricism / philosophical empiricism / principle of empiricism', '[{"en":"Empiricism demands that theories be supported by observable data.","zh-TW":"經驗主義要求理論必須有可觀察的數據支持。"},{"en":"His approach to research was grounded in empiricism.","zh-TW":"他的研究方法以經驗主義為基礎。"}]', '{"adjective":"empiricist"}', NULL, 4, 2376, NULL),
(2377, 'employ', '/ɪmˈplɔɪ/', 'verb', '{"zh-TW":["僱用；使用","雇用；運用"],"en":["to give work to someone; to use","to give work to someone","to make use of"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"ploy","meaning":"fold/use (使用)"},"logic":"把人用進來，即「雇用」。"}', 'employ staff/methods; employ staff / employ a strategy / currently employed', '[{"en":"The company employs over 5,000 people.","zh-TW":"該公司僱用了5000多人。"},{"en":"We employ various strategies to boost sales.","zh-TW":"我們使用各種策略來促進銷售。"},{"en":"The company employs over 500 people.","zh-TW":"公司雇用超過500人。"},{"en":"She employed a new strategy to solve the problem.","zh-TW":"她運用了新策略來解決問題。"}]', '{"noun":"employment/employee/employer","verb":"employ","noun2":"employee","noun3":"employer"}', NULL, 2, 2377, 344),
(2378, 'employee', 'ɛmˈplɔɪiː', 'noun', '{"zh-TW":["員工；雇員","職員"],"en":["a person working for a company","a worker"]}', NULL, 'full-time employee/employee benefits', '[{"en":"Employees must complete safety training.","zh-TW":"員工必須完成安全培訓。"}]', '{"verb":"employ","noun":"employer","adjective":"employed"}', NULL, 3, 2378, 27),
(2379, 'employee benefits', '/ɪmˌplɔɪiː ˈbenɪfɪts/', 'noun', '{"zh-TW":["員工福利"],"en":["non-wage compensation provided to employees in addition to salary"]}', NULL, 'offer employee benefits / enhance employee benefits', '[{"en":"Comprehensive employee benefits helped the company attract top talent.","zh-TW":"全面的員工福利幫助公司吸引了頂尖人才。"},{"en":"Employee benefits include health insurance, pension, and paid leave.","zh-TW":"員工福利包括健康保險、退休金和帶薪假期。"}]', NULL, NULL, 5, 2379, NULL),
(2380, 'employee benefits package', '/ɪmˈplɔɪiː ˈbenɪfɪts ˈpækɪdʒ/', 'noun', '{"zh-TW":["員工福利套餐"],"en":["the collection of non-wage compensations offered to employees in addition to salary"]}', NULL, 'evaluate employee benefits package / competitive employee benefits package', '[{"en":"A comprehensive employee benefits package includes health and retirement plans.","zh-TW":"全面的員工福利套餐包括健康和退休計劃。"},{"en":"A competitive employee benefits package helps attract top candidates.","zh-TW":"有競爭力的員工福利套餐有助於吸引頂尖候選人。"}]', NULL, NULL, 5, 2380, NULL),
(2381, 'employee contract', '/ɪmˈplɔɪiː ˈkɒntrækt/', 'noun', '{"zh-TW":["雇用合約；勞動合約"],"en":["a legally binding agreement between an employer and employee specifying terms of work"]}', NULL, 'issue an employee contract / review the employee contract', '[{"en":"Every new hire must sign an employee contract before starting.","zh-TW":"每位新員工在入職前必須簽署雇用合約。"},{"en":"The employee contract outlines duties, salary, and termination conditions.","zh-TW":"雇用合約概述了職責、薪資和終止條件。"}]', NULL, NULL, 5, 2381, NULL),
(2382, 'employee engagement', '/ɪmˈplɔɪiː ɪnˈɡeɪdʒmənt/', 'noun', '{"zh-TW":["員工投入度；員工參與度"],"en":["the level of enthusiasm and commitment employees have toward their work"]}', NULL, 'measure employee engagement / improve employee engagement / employee engagement survey', '[{"en":"High employee engagement leads to better productivity and retention.","zh-TW":"高員工投入度帶來更好的生產力和留才率。"},{"en":"The annual engagement survey revealed areas for improvement.","zh-TW":"年度投入度調查揭示了需要改進的領域。"}]', '{"verb":"engage","adjective":"engaged"}', NULL, 5, 2382, NULL),
(2383, 'employee engagement survey', '/ɪmˈplɔɪiː ɪnˈɡeɪdʒmənt ˈsɜːrveɪ/', 'noun', '{"zh-TW":["員工敬業度調查"],"en":["a questionnaire measuring how motivated and committed employees are"]}', NULL, 'conduct an employee engagement survey / employee engagement survey results', '[{"en":"The employee engagement survey showed 75% of staff feel valued.","zh-TW":"員工敬業度調查顯示75%的員工感到受重視。"},{"en":"Acting on employee engagement survey results improves retention.","zh-TW":"根據員工敬業度調查結果採取行動改善了留任率。"}]', NULL, NULL, 5, 2383, NULL),
(2384, 'employee handbook', '/ɪmˌplɔɪiː ˈhændbʊk/', 'noun', '{"zh-TW":["員工手冊"],"en":["a document outlining company policies, procedures, and expectations for employees"]}', NULL, 'distribute the employee handbook / update the employee handbook', '[{"en":"New employees receive an employee handbook on their first day.","zh-TW":"新員工在第一天收到員工手冊。"},{"en":"The employee handbook was revised to include the new remote work policy.","zh-TW":"員工手冊修訂納入了新的遠程工作政策。"}]', NULL, NULL, 5, 2384, NULL),
(2385, 'employee stock ownership plan', '/ɪmˈplɔɪiː stɒk ˈoʊnərʃɪp plæn/', 'noun', '{"zh-TW":["員工持股計劃"],"en":["a benefit plan giving employees an ownership interest in the company"]}', NULL, 'implement an employee stock ownership plan / employee stock ownership plan contribution', '[{"en":"An employee stock ownership plan aligns worker interests with company performance.","zh-TW":"員工持股計劃使工人利益與公司績效保持一致。"},{"en":"Employees in the plan benefited from the company''s stock price increase.","zh-TW":"計劃中的員工從公司股價上漲中受益。"}]', '{"abbreviation":"ESOP"}', NULL, 5, 2385, NULL),
(2386, 'employer', 'ɪmˈplɔɪər', 'noun', '{"zh-TW":["雇主；僱主","用人單位"],"en":["a person or company that employs","an organization that hires"]}', NULL, 'current employer/prospective employer', '[{"en":"Please provide your current employer''s details.","zh-TW":"請提供您目前雇主的詳細信息。"}]', '{"verb":"employ","noun":"employment","adjective":"employing"}', NULL, 3, 2386, NULL),
(2387, 'employment agency', '/ɪmˈplɔɪmənt ˈeɪdʒənsi/', 'noun', '{"zh-TW":["職業介紹所；人力仲介"],"en":["a firm that helps match job seekers with employers"]}', NULL, 'use an employment agency / employment agency fee', '[{"en":"The company used an employment agency to fill specialist roles.","zh-TW":"公司通過職業介紹所填補了專業職位。"},{"en":"Employment agencies charge a placement fee based on salary.","zh-TW":"職業介紹所根據薪資收取安置費。"}]', NULL, NULL, 5, 2387, NULL),
(2388, 'employment contract', '/ɪmˈplɔɪmənt ˈkɒntrækt/', 'noun', '{"zh-TW":["僱傭合約；勞動合同"],"en":["a legal agreement between employer and employee outlining terms of work"]}', NULL, 'sign an employment contract / breach of employment contract', '[{"en":"She signed the employment contract before her start date.","zh-TW":"她在入職日期前簽署了僱傭合約。"},{"en":"The employment contract specifies salary, duties, and benefits.","zh-TW":"僱傭合約規定了薪資、職責和福利。"}]', '{"verb":"contract"}', NULL, 5, 2388, NULL),
(2389, 'employment law', '/ɪmˈplɔɪmənt lɔː/', 'noun', '{"zh-TW":["就業法；雇傭法"],"en":["the body of law governing the rights and duties of employers and employees"]}', NULL, 'employment law specialist / comply with employment law / employment law update', '[{"en":"The HR team consulted an employment law expert before the restructuring.","zh-TW":"人力資源團隊在重組前諮詢了就業法專家。"},{"en":"Understanding employment law is essential for all managers.","zh-TW":"了解就業法對所有管理者至關重要。"}]', NULL, NULL, 5, 2389, NULL),
(2390, 'empower', '/ɪmˈpaʊər/', 'verb', '{"zh-TW":["賦予權力；使能夠"],"en":["to give someone authority or confidence"]}', NULL, 'empower employees/women', '[{"en":"The training empowers employees to make decisions.","zh-TW":"培訓賦予員工做決定的能力。"},{"en":"Technology empowers small businesses to compete.","zh-TW":"技術使小企業能夠參與競爭。"}]', '{"noun":"empowerment","verb":"empower"}', NULL, 3, 2390, 737),
(2391, 'empowered', 'ɪmˈpaʊərd', 'adjective', '{"zh-TW":["被授權的；有能力的","賦權的"],"en":["given authority to act","made capable"]}', NULL, 'empowered employees/empowered to decide', '[{"en":"Managers are empowered to make decisions.","zh-TW":"經理們被授權做決定。"}]', '{"verb":"empower","noun":"empowerment"}', NULL, 3, 2391, NULL),
(2392, 'empty', '/ˈɛmpti/', 'adjective', '{"zh-TW":["空的"],"en":["containing nothing; not filled"]}', NULL, 'empty space / empty promise', '[{"en":"The meeting room is empty now.","zh-TW":"會議室現在是空的。"},{"en":"Don''t make empty promises.","zh-TW":"別做空洞的承諾。"}]', '{"adjective":"empty","verb":"empty","noun":"emptiness"}', NULL, 2, 2392, NULL),
(2393, 'emulate', '/ˈemjʊleɪt/', 'verb', '{"zh-TW":["仿效；模仿"],"en":["to match or surpass by imitation; to copy"]}', NULL, 'emulate success / emulate a model / emulate behavior', '[{"en":"New firms often emulate the strategies of industry leaders.","zh-TW":"新公司往往仿效行業領導者的策略。"},{"en":"Students are encouraged to emulate the writing style of great authors.","zh-TW":"學生被鼓勵仿效偉大作家的寫作風格。"}]', '{"noun":"emulation","adjective":"emulative"}', NULL, 3, 2393, NULL),
(2394, 'emulsify', '/''ɪˈmʌlsɪfaɪ/', 'verb', '{"zh-TW":["乳化；使乳化"],"en":["to combine two liquids that normally do not mix, such as oil and water, into a stable mixture"]}', NULL, 'emulsify the sauce / emulsify oil / emulsify with egg yolk', '[{"en":"Whisking egg yolks with oil helps to emulsify the mayonnaise.","zh-TW":"用蛋黃和油攪打有助於乳化美乃滋。"},{"en":"The chef uses lecithin as an emulsifier to create smooth, creamy sauces.","zh-TW":"廚師使用卵磷脂作為乳化劑，製作出順滑奶油般的醬汁。"}]', '{"noun":"emulsification","noun2":"emulsifier"}', NULL, 3, 2394, NULL),
(2395, 'enable', '/ɪˈneɪbəl/', 'verb', '{"zh-TW":["使能夠；啟用"],"en":["to make possible or allow","to make possible or provide the means for"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"able","meaning":"able (能夠)"},"logic":"使其能夠，即「使能夠」。"}', 'enable + 人 + to; enable access / enable growth', '[{"en":"The software enables users to track expenses.","zh-TW":"該軟體使用戶能夠追蹤支出。"},{"en":"This funding will enable further research.","zh-TW":"這筆資金將使進一步研究成為可能。"},{"en":"Technology enables people to work from home.","zh-TW":"科技使人們能在家工作。"},{"en":"The grant enabled her to continue her research.","zh-TW":"這筆補助使她能繼續研究。"}]', '{"verb":"enable","adjective":"enabling"}', NULL, 2, 2395, 345),
(2396, 'enact', '/ɪˈnækt/', 'verb', '{"zh-TW":["制定；頒布"],"en":["to make a bill into law"]}', NULL, 'enact legislation/a policy', '[{"en":"The government enacted new environmental regulations.","zh-TW":"政府制定了新的環境法規。"},{"en":"The law was enacted in 2020.","zh-TW":"該法律於2020年頒布。"}]', '{"noun":"enactment","verb":"enact"}', NULL, 2, 2396, NULL),
(2397, 'enclave', '/ˈenkleɪv/', 'noun', '{"zh-TW":["飛地；孤立地區"],"en":["a territory completely surrounded by another; a group or area distinct from its surroundings"]}', NULL, 'economic enclave / ethnic enclave / cultural enclave', '[{"en":"The industrial enclave offered tax advantages to attract foreign manufacturers.","zh-TW":"工業特區提供稅收優惠以吸引外國製造商。"},{"en":"The immigrant community formed a tight-knit cultural enclave in the city center.","zh-TW":"移民社區在市中心形成了一個緊密的文化飛地。"}]', NULL, NULL, 3, 2397, NULL),
(2398, 'enclosed', '/ɪnˈkləʊzd/', 'adjective', '{"zh-TW":["附件的；附上的"],"en":["included with a letter or document"]}', NULL, 'please find enclosed / enclosed herewith', '[{"en":"Please find enclosed a copy of the invoice.","zh-TW":"請查閱附件中的發票副本。"},{"en":"A brochure is enclosed for your reference.","zh-TW":"附上一份宣傳冊供您參考。"}]', '{"verb":"enclose","noun":"enclosure"}', NULL, 3, 2398, 111),
(2399, 'encompass', '/''ɪnˌkʌmpəs/', 'verb', '{"zh-TW":["包含；涵蓋；包括"],"en":["to surround and have or hold within; to include or cover a wide range of"]}', NULL, 'encompass a range / encompass all aspects / broadly encompass', '[{"en":"The new policy encompasses all aspects of workplace safety.","zh-TW":"新政策涵蓋了工作場所安全的所有方面。"},{"en":"The course encompasses both theoretical knowledge and practical skills.","zh-TW":"這門課程同時涵蓋了理論知識和實踐技能。"}]', '{"noun":"encompassment","adjective":"encompassing"}', NULL, 3, 2399, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2400, 'encompassing', '/''ɪnˌkʌmpəsɪŋ/', 'adjective', '{"zh-TW":["包羅萬象的；涵蓋廣泛的"],"en":["covering or including a large range of things; comprehensive"]}', NULL, 'all-encompassing / broad and encompassing / encompassing framework', '[{"en":"The new policy is all-encompassing and covers every aspect of employee conduct.","zh-TW":"新政策包羅萬象，涵蓋了員工行為的方方面面。"},{"en":"She developed an encompassing theory that drew from multiple disciplines.","zh-TW":"她發展了一個從多個學科汲取靈感的涵蓋廣泛的理論。"}]', '{"verb":"encompass","adverb":"encompassingly"}', NULL, 4, 2400, NULL),
(2401, 'encounter', '/ɪnˈkaʊntər/', 'verb / noun', '{"zh-TW":["遭遇；碰到","遭遇；偶遇"],"en":["to unexpectedly meet or face","to unexpectedly meet or face something"]}', '{"prefix":{"text":"en-","meaning":"in (在)"},"root":{"text":"counter","meaning":"against (對面)"},"logic":"在對面碰上，即「遭遇」。"}', 'encounter difficulties/problems; encounter problems / encounter difficulties', '[{"en":"We encountered several problems during installation.","zh-TW":"我們在安裝過程中遇到了幾個問題。"},{"en":"It was her first encounter with the CEO.","zh-TW":"這是她第一次與執行長碰面。"},{"en":"We encountered several problems along the way.","zh-TW":"我們一路上遇到了幾個問題。"},{"en":"I encountered an old friend at the airport.","zh-TW":"我在機場偶遇一位老朋友。"}]', '{"noun":"encounter","verb":"encounter"}', NULL, 3, 2401, NULL),
(2402, 'encourage', '/ɪnˈkɜːrɪdʒ/', 'verb', '{"zh-TW":["鼓勵；促進"],"en":["to give support or confidence"]}', NULL, 'encourage + 人 + to', '[{"en":"The manager encouraged her team to innovate.","zh-TW":"經理鼓勵她的團隊創新。"},{"en":"Low interest rates encourage borrowing.","zh-TW":"低利率鼓勵借貸。"}]', '{"noun":"encouragement","verb":"encourage","adjective":"encouraging"}', NULL, 3, 2402, 112),
(2403, 'encouragement', 'ɪnˈkɜːrɪdʒmənt', 'noun', '{"zh-TW":["鼓勵；激勵","支持"],"en":["support that motivates action","words that inspire confidence"]}', NULL, 'offer encouragement/positive encouragement', '[{"en":"Her encouragement helped the team succeed.","zh-TW":"她的鼓勵幫助團隊成功。"}]', '{"verb":"encourage","adjective":"encouraging","adverb":"encouragingly"}', NULL, 5, 2403, NULL),
(2404, 'encroachment', '/ɪnˈkrəʊtʃmənt/', 'noun', '{"zh-TW":["侵佔；侵犯"],"en":["the act of gradually going beyond proper limits; intrusion"]}', NULL, 'urban encroachment / encroachment on rights / land encroachment', '[{"en":"Coastal development resulted in encroachment on protected wetlands.","zh-TW":"沿海開發導致侵佔受保護的濕地。"},{"en":"The court ruled the fence construction was an encroachment on neighboring property.","zh-TW":"法院裁定建造圍欄是對鄰近房產的侵佔。"}]', '{"verb":"encroach","adjective":"encroaching"}', NULL, 4, 2404, NULL),
(2405, 'encryption', '/ɪnˈkrɪpʃən/', 'noun', '{"zh-TW":["加密"],"en":["the process of converting data into a secret code"]}', NULL, 'data encryption / end-to-end encryption', '[{"en":"The message uses end-to-end encryption.","zh-TW":"訊息使用端對端加密。"},{"en":"Encryption protects your data.","zh-TW":"加密保護你的資料。"}]', '{"verb":"encrypt","adjective":"encrypted"}', NULL, 4, 2405, NULL),
(2406, 'encumber', '/ɪnˈkʌmbər/', 'verb', '{"zh-TW":["抵押；使負擔"],"en":["to restrict property or assets with a debt or mortgage"]}', NULL, 'encumber an asset / encumber property / encumber a title', '[{"en":"The property was encumbered with a first and second mortgage.","zh-TW":"該財產被第一和第二抵押貸款抵押。"},{"en":"Do not encumber key assets without board approval.","zh-TW":"未經董事會批准不得抵押關鍵資產。"}]', '{"noun":"encumbrance","adjective":"encumbered"}', NULL, 3, 2406, NULL),
(2407, 'encumbrance', '/ɪnˈkʌmbrəns/', 'noun', '{"zh-TW":["負擔；抵押債務"],"en":["a claim, lien, or liability attached to an asset or property"]}', NULL, 'check for encumbrances / clear encumbrances', '[{"en":"The property was sold free of all encumbrances.","zh-TW":"房產以無任何負擔的方式出售了。"},{"en":"The title search revealed an outstanding encumbrance on the land.","zh-TW":"產權搜索揭示了土地上的未清償抵押債務。"}]', '{"verb":"encumber","adjective":"encumbered"}', NULL, 4, 2407, NULL),
(2408, 'end', '/ɛnd/', 'noun', '{"zh-TW":["結束；末端"],"en":["the final part","to finish"]}', NULL, 'at the end / end up', '[{"en":"At the end of the month, we review performance.","zh-TW":"月底我們會檢討績效。"},{"en":"The contract ends next year.","zh-TW":"合約明年到期。"}]', '{"noun":"end","verb":"end","adjective":"endless","noun2":"ending"}', NULL, 1, 2408, NULL),
(2409, 'end of contract', '/end əv ˈkɒntrækt/', 'noun', '{"zh-TW":["合約期滿"],"en":["the conclusion of a fixed-term employment or service agreement"]}', NULL, 'notify at end of contract / end of contract procedures', '[{"en":"She received a bonus at the end of her three-year contract.","zh-TW":"她在三年合約期滿時收到了獎金。"},{"en":"End of contract procedures include final settlement and document return.","zh-TW":"合約期滿程序包括最終結算和文件歸還。"}]', NULL, NULL, 5, 2409, NULL),
(2410, 'end user', '/end ˈjuːzər/', 'noun', '{"zh-TW":["最終用戶；終端用戶"],"en":["the person who ultimately uses a product or service"]}', NULL, 'understand the end user / end user needs', '[{"en":"The software is designed with the end user experience in mind.","zh-TW":"軟體的設計以最終用戶體驗為重心。"},{"en":"Feedback from end users guided the second version of the product.","zh-TW":"最終用戶的反饋指導了產品第二版的開發。"}]', NULL, NULL, 3, 2410, NULL),
(2411, 'end-of-day balance', '/end əv deɪ ˈbæləns/', 'noun', '{"zh-TW":["日終餘額"],"en":["the account balance recorded at the close of a business day"]}', NULL, 'check end-of-day balance / report end-of-day balance', '[{"en":"The bank sends an automated end-of-day balance notification.","zh-TW":"銀行發送自動化的日終餘額通知。"},{"en":"Treasury monitors the end-of-day balance to plan overnight financing.","zh-TW":"財務部門監控日終餘額以計劃隔夜融資。"}]', NULL, NULL, 5, 2411, NULL),
(2412, 'end-of-year report', '/end əv jɪər rɪˈpɔːrt/', 'noun', '{"zh-TW":["年終報告"],"en":["a comprehensive summary of activities and performance for the full fiscal year"]}', NULL, 'prepare an end-of-year report / review the end-of-year report', '[{"en":"The end-of-year report highlighted key achievements and areas for improvement.","zh-TW":"年終報告強調了主要成就和改進領域。"},{"en":"Stakeholders use the end-of-year report to assess overall organizational performance.","zh-TW":"利益相關者使用年終報告評估整體組織績效。"}]', NULL, NULL, 5, 2412, NULL),
(2413, 'end-of-year review', '/end əv jɪər rɪˈvjuː/', 'noun', '{"zh-TW":["年終審查；年度回顧"],"en":["an evaluation of performance and results at the end of a fiscal year"]}', NULL, 'conduct an end-of-year review / prepare for end-of-year review', '[{"en":"The end-of-year review identified areas for improvement in Q1.","zh-TW":"年終審查識別了第一季度的改進領域。"},{"en":"All departments submitted end-of-year review reports by December 31.","zh-TW":"所有部門在12月31日前提交了年終審查報告。"}]', NULL, NULL, 5, 2413, NULL),
(2414, 'end-to-end', '/''end tə end/', 'adjective', '{"zh-TW":["端到端的；全流程的"],"en":["covering all stages of a process from beginning to end; encompassing the entire system"]}', NULL, 'end-to-end solution / end-to-end process / end-to-end visibility', '[{"en":"The platform provides an end-to-end solution for managing the entire supply chain.","zh-TW":"該平台為管理整個供應鏈提供了端到端的解決方案。"},{"en":"End-to-end visibility in logistics helps companies track shipments at every stage.","zh-TW":"物流中的端到端可見性幫助公司在每個階段追蹤貨物。"}]', '{"adverb":"end-to-end"}', NULL, 4, 2414, NULL),
(2415, 'endangered species', '/ɪnˈdeɪndʒərd ˈspiːʃiːz/', 'noun', '{"zh-TW":["瀕危物種"],"en":["a species at risk of becoming extinct"]}', NULL, 'protect endangered species / list of endangered species', '[{"en":"Polar bears are classified as an endangered species.","zh-TW":"北極熊被列為瀕危物種。"},{"en":"Conservation programs help protect endangered species.","zh-TW":"保育計劃有助於保護瀕危物種。"}]', NULL, NULL, 5, 2415, NULL),
(2416, 'endemic', '/enˈdemɪk/', 'adjective', '{"zh-TW":["地方性的；特有的；流行性的"],"en":["regularly found among a particular group or area; widespread in a community"]}', NULL, 'endemic disease / endemic poverty / endemic corruption', '[{"en":"Malaria remains endemic in many tropical regions despite control efforts.","zh-TW":"儘管進行了控制工作，瘧疾在許多熱帶地區仍然是地方病。"},{"en":"Endemic corruption erodes public trust in government institutions.","zh-TW":"地方性腐敗侵蝕了公眾對政府機構的信任。"}]', '{"noun":"endemism","adverb":"endemically"}', NULL, 3, 2416, NULL),
(2417, 'endocrinologist', '/ˌendəʊkrɪˈnɒlədʒɪst/', 'noun', '{"zh-TW":["內分泌科醫師"],"en":["a specialist in disorders of the endocrine system and hormones"]}', NULL, 'consult an endocrinologist / qualified endocrinologist / referred to an endocrinologist', '[{"en":"The endocrinologist managed the patient''s thyroid disorder.","zh-TW":"內分泌科醫師管理患者的甲狀腺疾病。"},{"en":"Hormonal imbalances often require the expertise of an endocrinologist.","zh-TW":"荷爾蒙失衡通常需要內分泌科醫師的專業知識。"}]', NULL, NULL, 5, 2417, NULL),
(2418, 'endogenous', '/enˈdɒdʒɪnəs/', 'adjective', '{"zh-TW":["內源性的；內生的"],"en":["originating from within a system or organism"]}', NULL, 'endogenous growth / endogenous variable / endogenous factor', '[{"en":"Endogenous growth theory argues that innovation drives long-term growth.","zh-TW":"內生增長理論認為創新推動長期增長。"},{"en":"The model distinguishes between endogenous and exogenous variables.","zh-TW":"模型區分了內生和外生變量。"}]', '{"adverb":"endogenously","antonym":"exogenous"}', NULL, 4, 2418, NULL),
(2419, 'endorphin', '/''endɔːrfɪn/', 'noun', '{"zh-TW":["腦內啡；內啡肽"],"en":["a chemical released in the brain during exercise that relieves pain and creates feelings of pleasure"]}', NULL, 'release endorphins / endorphin rush / natural endorphin', '[{"en":"Exercise releases endorphins that naturally boost mood and reduce stress.","zh-TW":"運動會釋放腦內啡，自然地提升情緒並減輕壓力。"},{"en":"The endorphin rush after a long run is sometimes called the ''runner''s high.''","zh-TW":"長跑後的腦內啡湧現有時被稱為「跑者的愉悅感」。"}]', NULL, NULL, 3, 2419, NULL),
(2420, 'endorse', '/ɪnˈdɔːrs/', 'verb', '{"zh-TW":["背書；認可"],"en":["to publicly approve or support"]}', NULL, 'endorse a product/candidate', '[{"en":"Several celebrities endorsed the brand.","zh-TW":"多位名人為該品牌背書。"},{"en":"The board endorsed the new strategy.","zh-TW":"董事會認可了新策略。"}]', '{"noun":"endorsement","verb":"endorse"}', NULL, 3, 2420, 867),
(2421, 'endorsement', '/ɪnˈdɔːrsmənt/', 'noun', '{"zh-TW":["代言；背書"],"en":["public approval or support given by a prominent person or organization"]}', NULL, 'celebrity endorsement / brand endorsement / endorsement deal', '[{"en":"The athlete''s endorsement boosted product sales by 40%.","zh-TW":"這位運動員的代言使產品銷售額提升了40%。"},{"en":"An official endorsement from an industry body builds credibility.","zh-TW":"行業機構的官方背書建立了可信度。"}]', '{"verb":"endorse","noun":"endorser"}', NULL, 4, 2421, 781),
(2422, 'endorsement fee', '/ɪnˈdɔːrsmənt fiː/', 'noun', '{"zh-TW":["代言費；背書費"],"en":["payment made to a person or organization for promoting a product"]}', NULL, 'negotiate endorsement fees / pay endorsement fees', '[{"en":"The athlete earned a substantial endorsement fee for the campaign.","zh-TW":"運動員為廣告活動賺取了可觀的代言費。"},{"en":"Endorsement fees are a significant part of celebrity income.","zh-TW":"代言費是名人收入的重要組成部分。"}]', NULL, NULL, 5, 2422, NULL),
(2423, 'endorsement letter', '/ɪnˈdɔːrsmənt ˈlɛtər/', 'noun', '{"zh-TW":["推薦函；背書信"],"en":["a letter recommending a person or product"]}', NULL, 'write an endorsement letter / receive an endorsement letter', '[{"en":"The professor provided an endorsement letter for the scholarship.","zh-TW":"教授為獎學金申請提供了推薦函。"},{"en":"An endorsement letter from a client strengthens the proposal.","zh-TW":"來自客戶的背書信加強了提案。"}]', NULL, NULL, 5, 2423, NULL),
(2424, 'endowment', '/ɪnˈdaʊmənt/', 'noun', '{"zh-TW":["捐贈基金；捐款"],"en":["a fund or gift made to an institution for a specific purpose"]}', NULL, 'endowment fund / university endowment / establish an endowment', '[{"en":"The university endowment funds research and scholarships.","zh-TW":"大學捐贈基金支持研究和獎學金。"},{"en":"She made a substantial endowment to the hospital foundation.","zh-TW":"她向醫院基金會捐贈了一大筆款項。"}]', '{"verb":"endow"}', NULL, 3, 2424, NULL),
(2425, 'endurance', '/''ɪnˈdjʊərəns/', 'noun', '{"zh-TW":["耐力；持久力"],"en":["the ability to sustain prolonged physical or mental effort"]}', NULL, 'build endurance / test endurance / endurance training', '[{"en":"Marathon runners spend months building their endurance before race day.","zh-TW":"馬拉松跑者在比賽日前花幾個月時間訓練耐力。"},{"en":"Mental endurance is just as important as physical endurance in competitive sports.","zh-TW":"在競技運動中，精神耐力與體能耐力同樣重要。"}]', '{"adjective":"enduring","verb":"endure"}', NULL, 3, 2425, NULL),
(2426, 'endurance sport', '/''enˌdjʊərəns spɔːrt/', 'noun', '{"zh-TW":["耐力運動"],"en":["a type of sport that requires sustained physical effort over a long period, such as marathon running or cycling"]}', NULL, 'participate in endurance sports / endurance sport training / popular endurance sport', '[{"en":"Marathon running is one of the most demanding endurance sports in the world.","zh-TW":"馬拉松是世界上最具挑戰性的耐力運動之一。"},{"en":"Training for endurance sports requires both physical conditioning and mental toughness.","zh-TW":"訓練耐力運動既需要體能調整，也需要心理韌性。"}]', '{"noun":"endurance"}', NULL, 5, 2426, NULL),
(2427, 'enemy', '/ˈɛnəmi/', 'noun', '{"zh-TW":["敵人；敵方"],"en":["a person who is hostile to another"]}', NULL, 'worst enemy / make enemies', '[{"en":"Procrastination is your worst enemy.","zh-TW":"拖延是你最大的敵人。"},{"en":"Don''t make enemies in the industry.","zh-TW":"別在業界樹敵。"}]', '{"noun":"enemy","noun2":"enmity"}', NULL, 2, 2427, NULL),
(2428, 'energy', 'ˈɛnərdʒi', 'noun', '{"zh-TW":["能量；精力","能源"],"en":["the capacity to do work","enthusiasm and vitality"]}', NULL, 'renewable energy/full of energy', '[{"en":"The company is shifting to renewable energy.","zh-TW":"公司正在轉向可再生能源。"}]', '{"adjective":"energetic","adverb":"energetically"}', NULL, 2, 2428, NULL),
(2429, 'energy efficiency', '/ˈɛnərdʒi ɪˈfɪʃənsi/', 'noun', '{"zh-TW":["能源效率"],"en":["using less energy to provide the same level of service"]}', NULL, 'improve energy efficiency / energy efficiency standard', '[{"en":"New appliances are designed for greater energy efficiency.","zh-TW":"新家電的設計旨在提高能源效率。"},{"en":"Energy efficiency reduces both costs and environmental impact.","zh-TW":"能源效率降低了成本和環境影響。"}]', '{"adjective":"energy-efficient","adverb":"efficiently"}', NULL, 5, 2429, NULL),
(2430, 'enforce', '/ɪnˈfɔːrs/', 'verb', '{"zh-TW":["執行；強制","執行；強制實施"],"en":["to compel compliance with a law or rule","to make sure a law or rule is obeyed"]}', NULL, 'enforce regulations/rules; enforce the law / strictly enforced', '[{"en":"The police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The contract will be strictly enforced.","zh-TW":"合約將被嚴格執行。"},{"en":"Police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The rules are strictly enforced.","zh-TW":"規則被嚴格執行。"}]', '{"noun":"enforcement","verb":"enforce","adjective":"enforceable"}', NULL, 3, 2430, 677),
(2431, 'enforceable', '/ɪnˈfɔːrsəbəl/', 'adjective', '{"zh-TW":["可執行的；有法律效力的"],"en":["legally valid and capable of being enforced by courts"]}', NULL, 'legally enforceable / enforceable contract / make enforceable', '[{"en":"The agreement must be written to be legally enforceable.","zh-TW":"協議必須以書面形式才具有法律執行力。"},{"en":"Not all verbal agreements are enforceable in court.","zh-TW":"並非所有口頭協議都在法庭上具有可執行性。"}]', '{"verb":"enforce","noun":"enforcement"}', NULL, 4, 2431, NULL),
(2432, 'enforcement mechanism', '/ɪnˈfɔːrsmənt ˈmekənɪzəm/', 'noun', '{"zh-TW":["執行機制"],"en":["a system of rules and consequences ensuring compliance"]}', NULL, 'effective enforcement mechanism / weak enforcement mechanism / create an enforcement mechanism', '[{"en":"An effective enforcement mechanism is essential for regulatory compliance.","zh-TW":"有效的執行機制對法規遵循至關重要。"},{"en":"International agreements often lack binding enforcement mechanisms.","zh-TW":"國際協議往往缺乏具有約束力的執行機制。"}]', NULL, NULL, 5, 2432, NULL),
(2433, 'engage', '/ɪnˈɡeɪdʒ/', 'verb', '{"zh-TW":["【主要意義-動詞】吸引（注意力）；使參與","【次要意義-動詞】雇用；聘請（正式）","【次要意義-動詞】（齒輪/機器）嚙合；接合","【次要意義-動詞】與……交涉；與……接觸"],"en":["[primary] to attract and keep attention; to involve someone","[secondary] to hire or employ someone for a specific purpose","[secondary] to connect mechanical parts together; to put into gear","[secondary] to enter into discussion or conflict with someone"]}', '{"prefix":{"text":"en-","meaning":"in (進入)"},"root":{"text":"gage","meaning":"pledge (承諾)"},"logic":"進入承諾參與，即「參與」。"}', 'engage a consultant / engage with stakeholders / engage the clutch / fully engaged', '[{"en":"The company engaged a top law firm to handle the acquisition.","zh-TW":"公司聘請了一家頂級律師事務所來處理此次收購。"},{"en":"Management must engage with employees to address the low morale issue.","zh-TW":"管理層必須與員工進行溝通，以解決士氣低落的問題。"},{"en":"The new campaign effectively engages customers through interactive content.","zh-TW":"新活動通過互動內容有效地吸引了客戶。"}]', '{"noun":"engagement","adjective":"engaging"}', '動詞 engage = 「聘請」（engage a consultant = 聘請顧問）是正式書面英語用法，engage with（與……接觸/溝通）是 TOEIC 商業和管理文章的高頻表達，考生常誤以為只有「吸引注意力」的意思。', 2, 2433, 346),
(2434, 'engaged', 'ɪnˈɡeɪdʒd', 'adjective', '{"zh-TW":["投入的；積極的","參與的"],"en":["busy with or involved in","committed to work"]}', NULL, 'highly engaged/employee engaged', '[{"en":"Engaged employees are more productive.","zh-TW":"積極投入的員工更有生產力。"}]', '{"verb":"engage","noun":"engagement"}', NULL, 3, 2434, NULL),
(2435, 'engagement', '/ɪnˈɡeɪdʒmənt/', 'noun', '{"zh-TW":["互動；參與度"],"en":["interactions such as likes, comments, shares, and clicks on content"]}', NULL, 'social media engagement / engagement rate / increase engagement', '[{"en":"High engagement on the post signaled strong audience interest.","zh-TW":"貼文上的高互動率表明了強烈的受眾興趣。"},{"en":"Video content typically drives higher engagement than static images.","zh-TW":"視頻內容通常比靜態圖片產生更高的互動率。"}]', '{"verb":"engage","adjective":"engaging"}', NULL, 4, 2435, 557),
(2436, 'engagement rate', '/ɪnˈɡeɪdʒmənt reɪt/', 'noun', '{"zh-TW":["互動率；參與率"],"en":["the level of interaction an audience has with content or a brand"]}', NULL, 'measure engagement rate / high engagement rate / improve engagement', '[{"en":"The Instagram post had an engagement rate of 8%.","zh-TW":"Instagram貼文的互動率為8%。"},{"en":"Engagement rate is a better measure of audience connection than follower count.","zh-TW":"互動率比追蹤者數量更能衡量受眾連結。"}]', NULL, NULL, 5, 2436, NULL),
(2437, 'engender', '/ɪnˈdʒendər/', 'verb', '{"zh-TW":["引起；產生"],"en":["to cause or give rise to a feeling, situation, or condition"]}', NULL, 'engender trust / engender conflict / engender growth', '[{"en":"Transparent governance policies engender public trust in institutions.","zh-TW":"透明的治理政策能夠在機構中培養公眾信任。"},{"en":"Poor working conditions engender low morale and high staff turnover.","zh-TW":"惡劣的工作條件會引起士氣低落和員工高流失率。"}]', NULL, NULL, 3, 2437, NULL),
(2438, 'engine', '/ˈɛndʒɪn/', 'noun', '{"zh-TW":["引擎；發動機"],"en":["a machine that converts energy into motion"]}', NULL, 'search engine / engine of growth', '[{"en":"Use a search engine to find information.","zh-TW":"使用搜尋引擎查找資訊。"},{"en":"Technology is the engine of growth.","zh-TW":"科技是成長的引擎。"}]', '{"noun":"engine","noun2":"engineer","noun3":"engineering"}', NULL, 2, 2438, NULL),
(2439, 'enhance', '/ɪnˈhæns/', 'verb', '{"zh-TW":["增強；提高","增強；提升"],"en":["to improve the quality or value of","to improve the quality or value of something"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"hance","meaning":"high (高)"},"logic":"使其提高，即「增強」。"}', 'enhance performance/productivity; enhance performance / enhance quality / enhance the experience', '[{"en":"The update will enhance system performance.","zh-TW":"更新將增強系統性能。"},{"en":"Training enhances employee productivity.","zh-TW":"培訓提高員工生產力。"},{"en":"This software enhances image quality.","zh-TW":"這個軟體增強了影像品質。"},{"en":"The new features enhance the user experience.","zh-TW":"新功能提升了使用者體驗。"}]', '{"noun":"enhancement","verb":"enhance"}', NULL, 3, 2439, 113),
(2440, 'enhancement', 'ɪnˈhɑːnsmənt', 'noun', '{"zh-TW":["增強；改善","提升"],"en":["an improvement","making better"]}', NULL, 'product enhancement/service enhancement', '[{"en":"The software update includes several enhancements.","zh-TW":"軟體更新包含幾項改進。"}]', '{"verb":"enhance","adjective":"enhanced"}', NULL, 4, 2440, 558),
(2441, 'enjoy', '/ɪnˈdʒɔɪ/', 'verb', '{"zh-TW":["享受；喜歡"],"en":["to get pleasure from something"]}', NULL, 'enjoy doing / enjoy the benefits', '[{"en":"I enjoy working with this team.","zh-TW":"我喜歡和這個團隊一起工作。"},{"en":"Members enjoy special benefits.","zh-TW":"會員享有特殊福利。"}]', '{"verb":"enjoy","noun":"enjoyment","adjective":"enjoyable"}', NULL, 2, 2441, NULL),
(2442, 'enormous', '/ɪˈnɔːrməs/', 'adjective', '{"zh-TW":["巨大的"],"en":["very large in size, quantity, or extent","very large in size or quantity"]}', '{"prefix":{"text":"e-","meaning":"out (超出)"},"root":{"text":"norm","meaning":"rule/standard (標準)"},"suffix":{"text":"-ous","meaning":"having (具有)"},"logic":"超出正常標準的，即「巨大的」。"}', 'enormous amount/potential; enormous amount / enormous pressure / enormous success', '[{"en":"The project requires an enormous investment.","zh-TW":"該項目需要巨額投資。"},{"en":"There is enormous potential for growth.","zh-TW":"有巨大的增長潛力。"},{"en":"The project requires an enormous amount of work.","zh-TW":"這個專案需要大量的工作。"},{"en":"The concert was an enormous success.","zh-TW":"音樂會獲得了巨大的成功。"}]', '{"adjective":"enormous","adverb":"enormously"}', NULL, 3, 2442, NULL),
(2443, 'enough', '/ɪˈnʌf/', 'adjective', '{"zh-TW":["足夠的"],"en":["as much as is needed"]}', NULL, 'good enough / not enough', '[{"en":"We don''t have enough staff for this project.","zh-TW":"我們沒有足夠的人手做這個專案。"},{"en":"Is this good enough?","zh-TW":"這樣夠好嗎？"}]', '{"adjective":"enough","adverb":"enough"}', NULL, 2, 2443, NULL),
(2444, 'enroll', '/ɪnˈroʊl/', 'verb', '{"zh-TW":["註冊；登記","註冊；入學"],"en":["to officially register for a course or program","to officially join a course or school"]}', NULL, 'enroll in a course/program; enroll in / enrollment period', '[{"en":"Over 500 students enrolled in the program.","zh-TW":"超過500名學生註冊了該計畫。"},{"en":"You can enroll online.","zh-TW":"你可以在線上註冊。"},{"en":"She enrolled in a language course.","zh-TW":"她報名了一門語言課程。"},{"en":"Over 500 students enrolled this year.","zh-TW":"今年有超過500名學生入學。"}]', '{"noun":"enrollment","verb":"enroll"}', NULL, 2, 2444, NULL),
(2445, 'enrollment', '/ɪnˈrəʊlmənt/', 'noun', '{"zh-TW":["入學；註冊"],"en":["the act of registering for a course or school"]}', NULL, 'enrollment period / course enrollment', '[{"en":"Enrollment for the spring semester begins in January.","zh-TW":"春季學期的入學從一月開始。"},{"en":"The school saw a 10% increase in enrollment this year.","zh-TW":"學校今年的入學人數增加了10%。"}]', '{"verb":"enroll","adjective":"enrolled"}', NULL, 4, 2445, 347),
(2446, 'ensure', '/ɪnˈʃʊr/', 'verb', '{"zh-TW":["確保"],"en":["to make certain that something happens"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"使其確定，即「確保」。"}', 'ensure quality/safety; ensure quality / ensure safety / ensure that', '[{"en":"Please ensure all data is backed up.","zh-TW":"請確保所有資料都已備份。"},{"en":"We must ensure customer satisfaction.","zh-TW":"我們必須確保客戶滿意度。"},{"en":"Please ensure all doors are locked.","zh-TW":"請確保所有門都已上鎖。"},{"en":"We must ensure the safety of our employees.","zh-TW":"我們必須確保員工的安全。"}]', '{"verb":"ensure"}', NULL, 2, 2446, 114),
(2447, 'enter', '/ˈɛntər/', 'verb', '{"zh-TW":["進入；輸入"],"en":["to go into a place","to type data"]}', NULL, 'enter the market / enter data', '[{"en":"They plan to enter the Asian market.","zh-TW":"他們計畫進入亞洲市場。"},{"en":"Please enter your password.","zh-TW":"請輸入你的密碼。"}]', '{"verb":"enter","noun":"entrance","noun2":"entry"}', NULL, 2, 2447, NULL),
(2448, 'enterprise', '/ˈentərpraɪz/', 'noun', '{"zh-TW":["企業；事業"],"en":["a business or company; a bold undertaking"]}', NULL, 'private/state enterprise', '[{"en":"Small enterprises drive economic growth.","zh-TW":"小型企業推動經濟增長。"},{"en":"The new enterprise launched last quarter.","zh-TW":"新企業上季度啟動了。"}]', '{"noun":"enterprise","adjective":"enterprising"}', NULL, 4, 2448, 348),
(2449, 'enterprise resource planning', '/ˈentərpraɪz rɪˈsɔːrs ˈplænɪŋ/', 'noun', '{"zh-TW":["企業資源規劃"],"en":["integrated software managing core business processes across departments"]}', NULL, 'implement ERP / ERP system / ERP migration', '[{"en":"The ERP system connects finance, HR, and supply chain in one platform.","zh-TW":"ERP系統將財務、人力資源和供應鏈連接在一個平台上。"},{"en":"Implementing ERP reduced data duplication and improved reporting.","zh-TW":"實施ERP減少了資料重複並改善了報告。"}]', '{"abbreviation":"ERP"}', NULL, 5, 2449, NULL);